    ];
    for args in cases {
        let out = run_wrapfile(&args);
        assert_eq!(exit_code(&out), 2, "args {args:?} must exit 2");
        assert!(
            stderr(&out).contains("Usage:"),
            "args {args:?} must print usage on stderr, got: {}",
            stderr(&out)
        );
        assert!(!key.exists(), "args {args:?} must not create a file");
    }
